  Lemma lb_bytes_nonneg : forall s LB m bs, as_RHEAP H s LB m -> (forall b, In b bs -> In b LB) -> 0 <= lb_bytes bs.
  Proof.
    intros s LB m bs HP. induction bs as [|c bs IH]; intros SUB; [cbn; lia|]. rewrite lb_bytes_cons.
    pose proof (ah_blocks H HH _ _ _ c HP (SUB c (or_introl eq_refl))) as (_ & _ & K3 & _).
    specialize (IH ltac:(intros b Hb; apply SUB; right; exact Hb)). lia.
  Qed.

  Lemma bcost_le_Cm : forall s LB m bs, as_RHEAP H s LB m -> (forall b, In b bs -> In b LB) -> bcost H bs <= as_Cm H (lb_bytes bs).
  Proof.
    intros s LB m bs HP. pose proof (ah_costs H HH) as (CM0 & CMM & CF0 & CFM & CMS & CFS). destruct H8 as [CFCM _].
    induction bs as [|c bs IH]; intros SUB; cbn [bcost]; [cbn; exact (CM0 0 ltac:(lia))|]. rewrite lb_bytes_cons.
    pose proof (ah_blocks H HH _ _ _ c HP (SUB c (or_introl eq_refl))) as (_ & _ & K3 & _).
    pose proof (lb_bytes_nonneg _ _ _ bs HP ltac:(intros b Hb; apply SUB; right; exact Hb)) as NN.
    specialize (IH ltac:(intros b Hb; apply SUB; right; exact Hb)).
    pose proof (CFCM _ K3). pose proof (CMS _ _ K3 NN). lia.
  Qed.

  (* [comment removed for export] *)
  Lemma bcost_le_Cf : forall s LB m bs, as_RHEAP H s LB m -> (forall b, In b bs -> In b LB) -> bcost H bs <= as_Cf H (lb_bytes bs).
  Proof.
    intros s LB m bs HP. pose proof (ah_costs H HH) as (CM0 & CMM & CF0 & CFM & CMS & CFS).
    induction bs as [|c bs IH]; intros SUB; cbn [bcost]; [cbn; exact (CF0 0 ltac:(lia))|]. rewrite lb_bytes_cons.
    pose proof (ah_blocks H HH _ _ _ c HP (SUB c (or_introl eq_refl))) as (_ & _ & K3 & _).
    pose proof (lb_bytes_nonneg _ _ _ bs HP ltac:(intros b Hb; apply SUB; right; exact Hb)) as NN.
    specialize (IH ltac:(intros b Hb; apply SUB; right; exact Hb)).
    pose proof (CFS _ _ K3 NN). lia.
  Qed.

  Lemma lb_bytes_sub : forall s LB m bs PB,
    as_RHEAP H s LB m -> (forall b, In b PB -> In b LB) -> List.NoDup (map blk_id bs) -> (forall b, In b bs -> In b PB) ->
    lb_bytes bs <= lb_bytes PB.
  Proof.
    intros s LB m bs. induction bs as [|c bs IH]; intros PB HP PBL ND SUB.
    - cbn. exact (lb_bytes_nonneg _ _ _ PB HP PBL).
    - destruct (in_split c PB (SUB c (or_introl eq_refl))) as (l1 & l2 & EPB). rewrite EPB. rewrite lb_bytes_app, !lb_bytes_cons.
      cbn in ND. pose proof (proj1 (List.NoDup_cons_iff _ _) ND) as [NI ND'].
      specialize (IH (l1 ++ l2) HP ltac:(intros b Hb; apply PBL; rewrite EPB; apply in_or_app; apply in_app_or in Hb; destruct Hb as [Hb|Hb]; [left; exact Hb| right; right; exact Hb]) ND').
      rewrite lb_bytes_app in IH.
      assert (SUB' : forall b, In b bs -> In b (l1 ++ l2)).
      { intros b Hb. pose proof (SUB b (or_intror Hb)) as K. rewrite EPB in K. apply in_app_or in K. apply in_or_app.
        destruct K as [K|[K|K]]; [left; exact K| | right; exact K]. exfalso. subst b. apply NI. apply in_map. exact Hb. }
      specialize (IH SUB'). lia.
  Qed.

  (* [comment removed for export] *)
  Lemma nodup_ids_app : forall s LB m l1 l2,
    as_RHEAP H s LB m -> (forall b, In b l1 -> In b LB) -> (forall b, In b l2 -> In b LB) ->
    List.NoDup (map blk_id l1) -> List.NoDup (map blk_id l2) ->
    (forall b1 b2, In b1 l1 -> In b2 l2 -> blk_addr b1 <> blk_addr b2) ->
    List.NoDup (map blk_id (l1 ++ l2)).
  Proof.
    intros s LB m l1 l2 HP S1 S2 N1 N2 DIF. rewrite map_app. apply base.NoDup_ListNoDup. apply list.NoDup_app.
    split; [apply base.NoDup_ListNoDup; exact N1|]. split; [| apply base.NoDup_ListNoDup; exact N2].
    intros i I1 I2. apply list_elem_of_In in I1. apply list_elem_of_In in I2.
    apply in_map_iff in I1. destruct I1 as (b1 & E1 & Hb1). apply in_map_iff in I2. destruct I2 as (b2 & E2 & Hb2).
    apply (DIF b1 b2 Hb1 Hb2). f_equal. eapply nodup_blk_eq; [exact (ah_nodup H HH _ _ _ HP)| exact (S1 _ Hb1)| exact (S2 _ Hb2)| rewrite E1, E2; reflexivity].
  Qed.

  Lemma Cf_zero : as_Cf H 0 = 0.
  Proof. pose proof (ah_costs H HH) as (_ & _ & CF0 & _ & _ & CFS). pose proof (CF0 0 ltac:(lia)) as U. pose proof (CFS 0 0 ltac:(lia) ltac:(lia)) as V. change (0 + 0) with 0 in V. lia. Qed.
